package br.com.helptech.v3;
import android.content.*;
public class BootReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())){try{org.json.JSONArray jobs=new org.json.JSONArray(c.getSharedPreferences("alarms",0).getString("jobs","[]"));for(int n=0;n<jobs.length();n++){org.json.JSONObject a=jobs.getJSONObject(n);String id=a.getString("id");if(c.getSharedPreferences("attended",0).getBoolean(id,false))continue;long at=java.time.LocalDateTime.parse(a.getString("date")+"T"+a.getString("time")).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()-3600000;if(at>System.currentTimeMillis())AlarmReceiver.set(c,id,a.optString("client"),a.optString("service"),a.optString("address"),at);}}catch(Exception e){}}}}
